import { useEffect, useState } from "react";
export function Dashboard({ orgId }: { orgId: string }) {
  const [rows, setRows] = useState([]);
  useEffect(() => { fetch(`/api/${orgId}`).then((r) => r.json()).then(setRows); }, []);
  return <pre>{rows.length}</pre>;
}

